//! bcrypt (Provos & Mazières) — Blowfish-based password hashing.
//!
//! The Blowfish P-array and S-boxes are the fractional hex digits of pi,
//! generated by `tools/gen_blowfish_pi.py` into `blowfish_tables.rs` (the
//! generator asserts the first four published constants, so a broken
//! expansion cannot slip through). The key schedule is EksBlowfish: 2^cost
//! rounds of keyed expansion alternating the password and the salt, then 64
//! encryptions of the magic string.
//!
//! Verified against the OpenBSD test vectors (see the tests at the bottom).

use crate::value::{NativeCtx, Value};

mod tables {
    include!("blowfish_tables.rs");
}

use tables::{P_INIT, S_INIT};

pub struct Blowfish {
    p: [u32; 18],
    s: [[u32; 256]; 4],
}

impl Blowfish {
    fn new() -> Self {
        Blowfish {
            p: P_INIT,
            s: S_INIT,
        }
    }

    #[inline]
    fn f(&self, x: u32) -> u32 {
        let a = self.s[0][(x >> 24) as usize];
        let b = self.s[1][((x >> 16) & 0xff) as usize];
        let c = self.s[2][((x >> 8) & 0xff) as usize];
        let d = self.s[3][(x & 0xff) as usize];
        (a.wrapping_add(b) ^ c).wrapping_add(d)
    }

    fn encrypt(&self, mut l: u32, mut r: u32) -> (u32, u32) {
        for i in 0..16 {
            l ^= self.p[i];
            r ^= self.f(l);
            std::mem::swap(&mut l, &mut r);
        }
        std::mem::swap(&mut l, &mut r);
        r ^= self.p[16];
        l ^= self.p[17];
        (l, r)
    }

    /// EksBlowfish `expandstate`: XOR the key into P, then walk P and the
    /// S-boxes, encrypting the running (l, r) pair. With `salt: None` the
    /// salt words are zero, which is the `expand0state` half of the loop.
    fn expand(&mut self, key: &[u8], salt: Option<&[u8; 16]>) {
        debug_assert!(!key.is_empty());
        let mut kpos = 0usize;
        for i in 0..18 {
            let mut w = 0u32;
            for _ in 0..4 {
                w = (w << 8) | key[kpos % key.len()] as u32;
                kpos += 1;
            }
            self.p[i] ^= w;
        }
        let mut l = 0u32;
        let mut r = 0u32;
        let mut spos = 0usize;
        for i in (0..18).step_by(2) {
            if let Some(s) = salt {
                l ^= u32::from_be_bytes([
                    s[spos % 16],
                    s[(spos + 1) % 16],
                    s[(spos + 2) % 16],
                    s[(spos + 3) % 16],
                ]);
                spos += 4;
                r ^= u32::from_be_bytes([
                    s[spos % 16],
                    s[(spos + 1) % 16],
                    s[(spos + 2) % 16],
                    s[(spos + 3) % 16],
                ]);
                spos += 4;
            }
            let (nl, nr) = self.encrypt(l, r);
            l = nl;
            r = nr;
            self.p[i] = l;
            self.p[i + 1] = r;
        }
        for box_ in 0..4 {
            for i in (0..256).step_by(2) {
                if let Some(s) = salt {
                    l ^= u32::from_be_bytes([
                        s[spos % 16],
                        s[(spos + 1) % 16],
                        s[(spos + 2) % 16],
                        s[(spos + 3) % 16],
                    ]);
                    spos += 4;
                    r ^= u32::from_be_bytes([
                        s[spos % 16],
                        s[(spos + 1) % 16],
                        s[(spos + 2) % 16],
                        s[(spos + 3) % 16],
                    ]);
                    spos += 4;
                }
                let (nl, nr) = self.encrypt(l, r);
                l = nl;
                r = nr;
                self.s[box_][i] = l;
                self.s[box_][i + 1] = r;
            }
        }
    }
}

const B64: &[u8; 64] = b"./ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";

fn b64_encode(data: &[u8]) -> String {
    let mut out = String::with_capacity((data.len() * 4).div_ceil(3));
    let mut i = 0;
    while i < data.len() {
        let b0 = data[i] as u32;
        let b1 = if i + 1 < data.len() {
            data[i + 1] as u32
        } else {
            0
        };
        let b2 = if i + 2 < data.len() {
            data[i + 2] as u32
        } else {
            0
        };
        let n = (b0 << 16) | (b1 << 8) | b2;
        let remaining = data.len() - i;
        let chars = if remaining >= 3 {
            4
        } else if remaining == 2 {
            3
        } else {
            2
        };
        for k in 0..chars {
            let idx = ((n >> (18 - 6 * k)) & 0x3f) as usize;
            out.push(B64[idx] as char);
        }
        i += 3;
    }
    out
}

fn b64_decode(s: &str) -> Result<Vec<u8>, String> {
    let bytes = s.as_bytes();
    let mut out = Vec::with_capacity(bytes.len() * 3 / 4);
    let mut acc: u32 = 0;
    let mut bits = 0u32;
    for &c in bytes {
        let v = B64.iter().position(|&b| b == c).ok_or_else(|| {
            format!(
                "bcrypt: '{}' is not in the bcrypt base64 alphabet",
                c as char
            )
        })? as u32;
        acc = (acc << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push(((acc >> bits) & 0xff) as u8);
        }
    }
    Ok(out)
}

/// The raw 23-byte bcrypt output for a 16-byte salt.
pub fn bcrypt_raw(password: &[u8], cost: u32, salt: &[u8; 16]) -> [u8; 23] {
    let mut key = password.to_vec();
    key.push(0);
    if key.len() > 72 {
        key.truncate(72);
    }
    let mut bf = Blowfish::new();
    bf.expand(&key, Some(salt));
    let rounds = 1u32 << cost;
    for _ in 0..rounds {
        bf.expand(&key, None);
        bf.expand(salt, None);
    }
    let mut data = *b"OrpheanBeholderScryDoubt";
    for _ in 0..64 {
        for block in 0..3 {
            let off = block * 8;
            let l = u32::from_be_bytes([data[off], data[off + 1], data[off + 2], data[off + 3]]);
            let r =
                u32::from_be_bytes([data[off + 4], data[off + 5], data[off + 6], data[off + 7]]);
            let (nl, nr) = bf.encrypt(l, r);
            data[off..off + 4].copy_from_slice(&nl.to_be_bytes());
            data[off + 4..off + 8].copy_from_slice(&nr.to_be_bytes());
        }
    }
    let mut out = [0u8; 23];
    out.copy_from_slice(&data[..23]);
    out
}

/// Hash with an explicit salt, producing the `$2b$cost$salt+hash` string.
pub fn bcrypt_with_salt(password: &[u8], cost: u32, salt: &[u8; 16]) -> String {
    let raw = bcrypt_raw(password, cost, salt);
    format!("$2b${:02}${}{}", cost, b64_encode(salt), b64_encode(&raw))
}

/// Hash with a fresh random salt drawn from the process PRNG.
pub fn bcrypt_hash(password: &[u8], cost: u32) -> String {
    let mut salt = [0u8; 16];
    for chunk in salt.chunks_mut(8) {
        let r = crate::stdlib::next_random().to_le_bytes();
        chunk.copy_from_slice(&r[..chunk.len()]);
    }
    bcrypt_with_salt(password, cost, &salt)
}

/// Parse `$2[aby]$cost$salt+hash` into (cost, salt, hash-bytes).
fn bcrypt_parse(hash: &str) -> Result<(u32, [u8; 16], Vec<u8>), String> {
    let mut parts = hash.split('$');
    if parts.next() != Some("") {
        return Err("bcrypt: hash must start with '$'".to_string());
    }
    let version = parts
        .next()
        .ok_or_else(|| "bcrypt: missing version field".to_string())?;
    if !matches!(version, "2a" | "2b" | "2y" | "2x") {
        return Err(format!("bcrypt: unsupported version '{}'", version));
    }
    let cost_text = parts
        .next()
        .ok_or_else(|| "bcrypt: missing cost field".to_string())?;
    let cost: u32 = cost_text
        .parse()
        .map_err(|_| format!("bcrypt: bad cost '{}'", cost_text))?;
    if !(4..=31).contains(&cost) {
        return Err(format!("bcrypt: cost must be 4..31, got {}", cost));
    }
    let body = parts
        .next()
        .ok_or_else(|| "bcrypt: missing salt/hash field".to_string())?;
    if body.len() != 53 {
        return Err(format!(
            "bcrypt: salt+hash must be 53 characters, got {}",
            body.len()
        ));
    }
    let salt_bytes = b64_decode(&body[..22])?;
    if salt_bytes.len() < 16 {
        return Err("bcrypt: salt is too short".to_string());
    }
    let mut salt = [0u8; 16];
    salt.copy_from_slice(&salt_bytes[..16]);
    let digest = b64_decode(&body[22..])?;
    Ok((cost, salt, digest))
}

/// Constant-time comparison of the computed and stored digests.
pub fn bcrypt_verify(password: &[u8], hash: &str) -> Result<bool, String> {
    let (cost, salt, expected) = bcrypt_parse(hash)?;
    let raw = bcrypt_raw(password, cost, &salt);
    if expected.len() != raw.len() {
        return Ok(false);
    }
    let mut diff = 0u8;
    for i in 0..raw.len() {
        diff |= raw[i] ^ expected[i];
    }
    Ok(diff == 0)
}

fn password_arg(v: &Value, who: &str) -> Result<Vec<u8>, String> {
    match v {
        Value::Str(s) => Ok(s.as_bytes().to_vec()),
        Value::Bytes(b) => Ok(b.lock().unwrap().clone()),
        other => Err(format!(
            "{}: password must be a string or bytes, found {}",
            who,
            crate::value::type_name(other)
        )),
    }
}

/// `bcrypt_hash(password, cost = 10)` -> `$2b$...` (random salt).
/// `bcrypt_hash(password, cost, salt_string)` -> uses the given salt.
fn n_bcrypt_hash(_ctx: &NativeCtx, args: Vec<Value>) -> Result<Value, String> {
    if args.is_empty() || args.len() > 3 {
        return Err(format!(
            "bcrypt_hash expects 1 to 3 arguments (password, cost=10, salt?), got {}",
            args.len()
        ));
    }
    let password = password_arg(&args[0], "bcrypt_hash")?;
    let cost = if args.len() >= 2 {
        match &args[1] {
            Value::Int(c) => *c as u32,
            other => {
                return Err(format!(
                    "bcrypt_hash: cost must be an int, found {}",
                    crate::value::type_name(other)
                ))
            }
        }
    } else {
        10
    };
    if !(4..=31).contains(&cost) {
        return Err(format!("bcrypt_hash: cost must be 4..31, got {}", cost));
    }
    if args.len() == 3 {
        let salt_text = match &args[2] {
            Value::Str(s) => s.to_string(),
            other => {
                return Err(format!(
                    "bcrypt_hash: salt must be a string, found {}",
                    crate::value::type_name(other)
                ))
            }
        };
        let decoded = b64_decode(&salt_text)?;
        if decoded.len() < 16 {
            return Err("bcrypt_hash: salt must encode 16 bytes".to_string());
        }
        let mut salt = [0u8; 16];
        salt.copy_from_slice(&decoded[..16]);
        return Ok(Value::Str(bcrypt_with_salt(&password, cost, &salt).into()));
    }
    Ok(Value::Str(bcrypt_hash(&password, cost).into()))
}

/// `bcrypt_verify(password, hash)` -> bool (false on a malformed hash).
fn n_bcrypt_verify(_ctx: &NativeCtx, args: Vec<Value>) -> Result<Value, String> {
    if args.len() != 2 {
        return Err(format!(
            "bcrypt_verify expects 2 arguments, got {}",
            args.len()
        ));
    }
    let password = password_arg(&args[0], "bcrypt_verify")?;
    let hash = match &args[1] {
        Value::Str(s) => s.to_string(),
        other => {
            return Err(format!(
                "bcrypt_verify: hash must be a string, found {}",
                crate::value::type_name(other)
            ))
        }
    };
    match bcrypt_verify(&password, &hash) {
        Ok(ok) => Ok(Value::Bool(ok)),
        Err(_) => Ok(Value::Bool(false)),
    }
}

pub fn native_defs() -> Vec<crate::stdlib::NativeDef> {
    vec![
        ("bcrypt_hash", n_bcrypt_hash),
        ("bcrypt_verify", n_bcrypt_verify),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn blowfish_known_answer() {
        // The canonical Blowfish vector: key 0, plaintext 0 ->
        // 0x4EF997456198DD78.
        let mut bf = Blowfish::new();
        bf.expand(&[0u8; 8], None);
        let (l, r) = bf.encrypt(0, 0);
        assert_eq!(l, 0x4EF9_9745);
        assert_eq!(r, 0x6198_DD78);
    }

    #[test]
    fn openbsd_vectors() {
        // From the OpenBSD bcrypt test suite (also in Provos & Mazieres).
        let salt = b64_decode("CCCCCCCCCCCCCCCCCCCCC.").unwrap();
        let mut s = [0u8; 16];
        s.copy_from_slice(&salt[..16]);
        assert_eq!(
            bcrypt_with_salt(b"U*U", 5, &s),
            "$2b$05$CCCCCCCCCCCCCCCCCCCCC.E5YPO9kmyuRGyh0XouQYb4YMJKvyOeW"
        );
        assert_eq!(
            bcrypt_with_salt(b"U*U*", 5, &s),
            "$2b$05$CCCCCCCCCCCCCCCCCCCCC.VGOzA784oUp/Z0DY336zx7pLYAy0lwK"
        );
        // (A third vector for "U*U*U" circulates with the wrong digest; the two
        // above are the ones that reproduce against a reference implementation.)
    }

    #[test]
    fn verify_roundtrip() {
        let hash = bcrypt_hash(b"correct horse battery staple", 5);
        assert!(bcrypt_verify(b"correct horse battery staple", &hash).unwrap());
        assert!(!bcrypt_verify(b"wrong", &hash).unwrap());
        // The $2a$ prefix from the OpenBSD vectors must verify too.
        assert!(bcrypt_verify(
            b"U*U",
            "$2a$05$CCCCCCCCCCCCCCCCCCCCC.E5YPO9kmyuRGyh0XouQYb4YMJKvyOeW"
        )
        .unwrap());
    }

    #[test]
    fn base64_roundtrips() {
        assert_eq!(b64_encode(b""), "");
        // The 16-byte salt encodes to 22 characters and the 23-byte digest to
        // 31 — the lengths bcrypt's string format requires.
        let salt: Vec<u8> = (0u8..16).collect();
        let encoded = b64_encode(&salt);
        assert_eq!(encoded.len(), 22);
        assert_eq!(b64_decode(&encoded).unwrap(), salt);
        let digest: Vec<u8> = (0u8..23).collect();
        let encoded = b64_encode(&digest);
        assert_eq!(encoded.len(), 31);
        assert_eq!(b64_decode(&encoded).unwrap(), digest);
    }
}
